package kr.releasepilot.controlplane.analysis;
import com.sun.net.httpserver.HttpServer;import org.junit.jupiter.api.*;import tools.jackson.databind.ObjectMapper;import java.net.*;import java.net.http.HttpClient;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.concurrent.atomic.AtomicReference;import static org.assertj.core.api.Assertions.assertThat;
class HttpAnalysisWorkerGatewayTests{
 private HttpServer server;@AfterEach void stop(){if(server!=null)server.stop(0);}
 @Test void sendsSnapshotContextAndReturnsEvidence()throws Exception{var received=new AtomicReference<String>();server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/v1/analyses",exchange->{received.set(new String(exchange.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));byte[] body="{\"verdict\":\"PASS\",\"reason_code\":\"ALL_RULES_PASSED\",\"evidence\":[{\"metric_key\":\"REQUEST_COUNT\"}]}".getBytes(StandardCharsets.UTF_8);exchange.sendResponseHeaders(200,body.length);exchange.getResponseBody().write(body);exchange.close();});server.start();var gateway=new HttpAnalysisWorkerGateway(HttpClient.newHttpClient(),new ObjectMapper(),"http://127.0.0.1:"+server.getAddress().getPort());var result=gateway.evaluate(new AnalysisWorkerGateway.Request("", "http://prometheus:9090","secret","prom-1","checksum",Instant.parse("2026-01-01T00:00:00Z"),Instant.parse("2026-01-01T00:05:00Z"),"shop","checkout","production","[{\"key\":\"REQUEST_COUNT\",\"required\":true,\"comparison\":\"GREATER_THAN_OR_EQUAL\",\"threshold\":1000}]"));assertThat(result.verdict()).isEqualTo(AnalysisVerdict.PASS);assertThat(result.evidenceJson()).contains("REQUEST_COUNT");assertThat(received.get()).contains("prometheus_url","policy_snapshot_checksum","\"bearer_token\":\"secret\"").doesNotContain("release_track");}
}
